import subprocess, shutil, os, glob
def fresh(name):
    d=f"/tmp/{name}"; shutil.rmtree(d, ignore_errors=True); os.makedirs(f"{d}/data"); os.makedirs(f"{d}/conf"); return d
def run(d,args):
    return subprocess.run(["./executable","-D",f"{d}/data","-C",f"{d}/conf"]+args, capture_output=True, text=True)
for ical in sorted(glob.glob("assets/*.ical")):
    if "_1" in ical: continue
    d=fresh("tt")
    r=run(d,["-i",ical]); out=r.stdout.strip().replace(chr(10)," | ")
