import subprocess, shutil, os, string
def fresh():
    d="/tmp/tt"; shutil.rmtree(d,ignore_errors=True); os.makedirs(f"{d}/data"); os.makedirs(f"{d}/conf"); return d
def run(d,args): return subprocess.run(["./executable","-D",f"{d}/data","-C",f"{d}/conf"]+args,capture_output=True,text=True)
for sep in string.printable.strip():
