# bywday encoding helpers
def encode_bywday(ordinal, weekday_sun0):
    if ordinal == 0: return weekday_sun0
    if ordinal > 0: return 7*ordinal + weekday_sun0
    return 7*ordinal - weekday_sun0
def decode_bywday(w):
    if 0 <= w <= 6: return (0,w)
    if w >= 7:
        return (w//7, w%7)
    # w <= -7
    aw = -w
    return (-(aw//7), aw % 7)

def monthday_matches(day_days, bymonthday):
    if not bymonthday: return True
    y,m,d = civil_from_days(day_days)
    dim = days_in_month(y,m)
    for v in bymonthday:
        if v > 0 and d == v: return True
        if v < 0 and d == dim+v+1: return True
    return False

def bywday_plain_matches(day_days, bywday):
    wd = weekday_sun0(day_days)
    for w in bywday:
        o,wd2 = decode_bywday(w)
        if wd2 == wd: return True
    return False

def nth_weekday_of_month(y,m,weekday,ordinal):
    dim = days_in_month(y,m)
    matches=[]
    first = days_from_civil(y,m,1)
    for d in range(1,dim+1):
        if weekday_sun0(first+d-1)==weekday: matches.append(d)
    if ordinal>0:
        return days_from_civil(y,m,matches[ordinal-1]) if ordinal<=len(matches) else None
    if ordinal<0:
        return days_from_civil(y,m,matches[ordinal]) if -ordinal<=len(matches) else None
    return None

def nth_weekday_of_year(y,weekday,ordinal):
    matches=[]
    first=days_from_civil(y,1,1); last=days_from_civil(y,12,31)
    z=first
    # first such weekday
    z += (weekday-weekday_sun0(z))%7
    while z<=last:
        matches.append(z); z+=7
    if ordinal>0: return matches[ordinal-1] if ordinal<=len(matches) else None
    if ordinal<0: return matches[ordinal] if -ordinal<=len(matches) else None
    return None

def is_occurrence_day(start_day, rpt: Rpt, day, firstday_monday=True):
    """Whether an occurrence *starts* on `day` (pattern and until, not exceptions)."""
    if day < start_day: return False
    if rpt.until is not None and day > rpt.until: return False
    sy,sm,sd = civil_from_days(start_day)
    y,m,d = civil_from_days(day)
    interval = rpt.freq
    if interval == 0:
        # original crashes with SIGFPE in some paths
        os.kill(os.getpid(), signal.SIGFPE); return False
    typ=rpt.typ
    if typ=='D':
        if cmod(day-start_day, interval) != 0: 
            # Python % is fine here as difference >=0 for positive intervals;
            # for negative intervals use C remainder test via modulo equality
            if (day-start_day) % interval != 0: return False
        if rpt.bymonth and m not in rpt.bymonth: return False
        if rpt.bymonthday and not monthday_matches(day,rpt.bymonthday): return False
        if rpt.bywday and not bywday_plain_matches(day,rpt.bywday): return False
        return True
    if typ=='W':
        # week index relative to week (starting Mon or Sun) containing start
        def week_start(z):
            wd=weekday_sun0(z)
            offset = (wd-1)%7 if firstday_monday else wd
            return z-offset
        wdiff = (week_start(day)-week_start(start_day))//7
        if wdiff < 0: return False
        if interval != 0 and (wdiff % interval != 0 if interval>0 else cmod(wdiff,interval)!=0): return False
        if rpt.bymonth and m not in rpt.bymonth: return False
        # BYMONTHDAY is illegal with WEEKLY in data files, but can arise
        # from iCalendar import; original then treats it as a limit when
        # checking occurrences in memory.
        if rpt.bymonthday and not monthday_matches(day,rpt.bymonthday): return False
        if rpt.bywday:
            return bywday_plain_matches(day,rpt.bywday)
        return weekday_sun0(day)==weekday_sun0(start_day)
    if typ=='M':
        mdiff = month_diff(sy,sm,y,m)
        if mdiff < 0: return False
        if interval>0 and mdiff % interval != 0: return False
        if interval<0 and cmod(mdiff,interval)!=0: return False
        if rpt.bymonth and m not in rpt.bymonth: return False
        return _month_day_candidate(start_day,rpt,day)
    if typ=='Y':
        ydiff = y-sy
        if ydiff < 0: return False
        if interval>0 and ydiff % interval != 0: return False
        if interval<0 and cmod(ydiff,interval)!=0: return False
        if rpt.bymonth:
            if m not in rpt.bymonth: return False
            return _month_day_candidate(start_day,rpt,day)
        # no BYMONTH
        if rpt.bywday and not rpt.bymonthday:
            # weekday expands over the whole year
            for w in rpt.bywday:
                o,wd = decode_bywday(w)
                if o==0:
                    if weekday_sun0(day)==wd: return True
                else:
                    if nth_weekday_of_year(y,wd,o)==day: return True
            return False
        # otherwise behaviour as in the start month only
        if m != sm: return False
        return _month_day_candidate(start_day,rpt,day)
    return False

def _month_day_candidate(start_day,rpt,day):
    sy,sm,sd = civil_from_days(start_day)
    y,m,d = civil_from_days(day)
    if rpt.bywday and rpt.bymonthday:
        return monthday_matches(day,rpt.bymonthday) and bywday_plain_matches(day,rpt.bywday)
    if rpt.bymonthday:
        return monthday_matches(day,rpt.bymonthday)
    if rpt.bywday:
        for w in rpt.bywday:
            o,wd=decode_bywday(w)
            if o==0:
                if weekday_sun0(day)==wd: return True
            else:
                if nth_weekday_of_month(y,m,wd,o)==day: return True
        return False
    return d==sd

def pattern_day(start_day,rpt,day,firstday_monday=True):
    """Occurrence pattern ignoring until and the day<start bound for the
    start-match tests performed while loading (until handled by caller)."""
    # implemented by temporarily clearing until
    old=rpt.until; rpt.until=None
    try:
        # for days before start the generic test is meaningless; callers
        # only use day>=start_day or search forward
        return is_occurrence_day(start_day,rpt,day,firstday_monday)
    finally:
        rpt.until=old

def find_candidate_for_day(item_start_day, rpt, dur, exc, day, firstday_monday=True):
    """Replicate recur_item_inday: search backwards for the latest
    pattern day <= day, then apply until/exceptions/overlap for that one."""
    if rpt is None: return None
    # How far back can an occurrence start and still overlap this day?
    # dur seconds; a zero-duration item only occurs on its start day.
    max_back = 0
    if dur and dur>0:
        max_back = (dur-1)//86400 + 1
        # searching one extra day is harmless because overlap is checked
        max_back += 1
    t=day
    low = max(item_start_day, day-max_back) if dur else day
    while t>=low and t>=item_start_day:
        # pattern irrespective of until/exceptions: use a shallow clone test
        saved=rpt.until; rpt.until=None
        occ = is_occurrence_day(item_start_day,rpt,t,firstday_monday)
        rpt.until=saved
        if occ:
            if rpt.until is not None and t>rpt.until: return None
            if t in (exc or []): return None
            return t
        t-=1
    return None

def recur_occurrence_on_day(start_dt, dur, rpt, exc, day, firstday_monday=True):
    """Return occurrence start wall dt that should be displayed on `day`, or None."""
    start_day = norm_dt(*start_dt)[0]
    cand_day = find_candidate_for_day(start_day,rpt,dur,exc,day,firstday_monday)
    if cand_day is None: return None
    occ_start=(cand_day, norm_dt(*start_dt)[1])
    if dur and dur>0:
        occ_end_total=dt_total(occ_start)+dur
        if occ_end_total <= day*86400: return None
        if dt_total(occ_start) >= (day+1)*86400: return None
    else:
        if cand_day != day: return None
    return occ_start

def next_occurrence_day(start_day,rpt,exc,after_day,firstday_monday=True,limit_days=40000):
    """First occurrence start day > after_day (or >= if after_day is None sentinel handled by caller)."""
    day=max(start_day, after_day+1)
    for _ in range(limit_days):
        if rpt.until is not None and day>rpt.until: return None
        if is_occurrence_day(start_day,rpt,day,firstday_monday) and day not in (exc or []):
            return day
        day+=1
    return None

