def get_home():
    h=os.environ.get("HOME")
    if h: return h
    try:
        import pwd; return pwd.getpwuid(os.getuid()).pw_dir
    except Exception: return ""

def resolve_dirs(datadir_arg, confdir_arg):
    home=get_home()
    legacy=os.path.join(home,".calcurse") if home else ".calcurse"
    has_legacy=os.path.exists(legacy)
    xdg_data=os.environ.get("XDG_DATA_HOME") or os.path.join(home,".local","share")
    xdg_conf=os.environ.get("XDG_CONFIG_HOME") or os.path.join(home,".config")
    def_datadir = legacy if has_legacy else os.path.join(xdg_data,"calcurse")
    def_confdir = legacy if has_legacy else os.path.join(xdg_conf,"calcurse")
    datadir = datadir_arg if datadir_arg is not None else def_datadir
    if confdir_arg is not None:
        confdir=confdir_arg
    elif datadir_arg is not None:
        confdir=datadir_arg
    else:
        confdir=def_confdir
    return datadir,confdir

def ensure_dir(path):
    if os.path.isdir(path): return
    # mkdir -p with mode 0700 for newly created components
    parts=[]
    p=path
    while p and not os.path.exists(p):
        parts.append(p); parent=os.path.dirname(p)
        if parent==p: break
        p=parent
    for comp in reversed(parts):
        try:
            os.mkdir(comp,0o700)
        except FileExistsError:
            pass
        except OSError as e:
            fatal(None,f"FATAL ERROR: could not create {comp}: {e.strerror}")

def check_dirs(env: Env):
    if env.readonly: return
    ensure_dir(env.datadir); ensure_dir(env.notes_dir)
    ensure_dir(env.confdir); ensure_dir(env.hooks_dir)

def check_files(env: Env, apts=False,todo=False,conf=False):
    if env.readonly: return
    for want,path in [(apts,env.apts_path),(todo,env.todo_path),(conf,env.conf_path)]:
        if want and not os.path.exists(path):
            try: open(path,'a').close()
            except OSError: pass

def run_hook(env,name):
    path=os.path.join(env.hooks_dir,name)
    try:
        if os.path.isfile(path) and os.access(path,os.X_OK):
            subprocess.run([path],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    except Exception:
        pass

# ---------------- raw formatting ----------------
def rpt_raw(rpt:Rpt, exc):
    s=f"{rpt.freq}{rpt.typ}"
    if rpt.until is not None: s+=f" -> {fmt_date_file(rpt.until)}"
    for v in rpt.bymonthday: s+=f" d{v}"
    for v in rpt.bywday: s+=f" w{v}"
    for v in rpt.bymonth: s+=f" m{v}"
    for e in sorted(exc or []): s+=f" !{fmt_date_file(e)}"
    return s

def raw_event(e: Event):
    s=f"{fmt_date_file(e.day)} [{e.id}]"
    if e.rpt: s+=f" {{{rpt_raw(e.rpt,e.exc)}}}"
    if e.note: s+=f" >{e.note}"
    s+=f" {e.mesg}"
    return s

def raw_apt(a: Apt):
    st=norm_dt(*a.start); en=dt_add_seconds(st,a.dur)
    s=f"{fmt_date_file(st[0])} @ {fmt_time_file(st[1])} -> {fmt_date_file(en[0])} @ {fmt_time_file(en[1])}"
    if a.rpt: s+=f" {{{rpt_raw(a.rpt,a.exc)}}}"
    if a.note: s+=f">{a.note} "
    elif a.rpt: s+=" "
    s+=f"{a.state}{a.mesg}"
    return s

def raw_todo(t: Todo):
    label=f"[-{t.id}]" if t.completed else f"[{t.id}]"
    s=label
    if t.note: s+=f">{t.note}"
    s+=f" {t.mesg}"
    return s

def raw_item(kind,obj):
    if kind=='todo': return raw_todo(obj)
    if kind in ('event','recur-event'): return raw_event(obj)
    return raw_apt(obj)
def item_hash(kind,obj):
    return hashlib.sha1(raw_item(kind,obj).encode('utf-8','surrogateescape')).hexdigest()

def write_store_files(env: Env):
    if env.readonly: return
    sort_store(env.store)
    # apts: recur events, recur apts, apts, events
    lines=[]
    for e in env.store.revents: lines.append(raw_event(e))
    for a in env.store.rapts: lines.append(raw_apt(a))
    for a in env.store.apts: lines.append(raw_apt(a))
    for e in env.store.events: lines.append(raw_event(e))
    try:
        with open(env.apts_path,'wb') as f:
            for l in lines: f.write(l.encode('utf-8','surrogateescape')+b'\n')
    except OSError: pass
    try:
        with open(env.todo_path,'wb') as f:
            for t in env.store.todos: f.write(raw_todo(t).encode('utf-8','surrogateescape')+b'\n')
    except OSError: pass

# ---------------- filters ----------------
@dataclass
class Filter:
    type_mask: object = None    # set of kinds or None
    regex: object = None        # PosixRegex
    hash_str: object = None
    invert: bool = False
    start_from: object = None   # wall total seconds
    start_to: object = None
    end_from: object = None
    end_to: object = None
    priority: object = None
    completed: bool = False
    uncompleted: bool = False

FILTER_TYPES={"event","apt","recur-event","recur-apt","todo"}
def parse_filter_type(s):
    result=set(); seen=False
    for tok in s.split(','):
        if tok=="":
            continue
        seen=True
        if tok=="cal": result|={"event","apt","recur-event","recur-apt"}
        elif tok=="recur": result|={"recur-event","recur-apt"}
        elif tok in FILTER_TYPES: result.add(tok)
        else: return None
    return result if seen else None

def c_abs(v):
    return -2147483648 if v==-2147483648 else abs(v)

def item_start_end(kind,obj):
    if kind in ('event','recur-event'):
        return obj.day*86400, obj.day*86400+86399
    st=dt_total(norm_dt(*obj.start)); return st, st+obj.dur

def filter_match(flt: Filter, kind, obj):
    if flt is None: return True
    ok=True
    if flt.type_mask is not None and kind not in flt.type_mask: ok=False
    if ok and flt.regex is not None:
        if not flt.regex.search(obj.mesg): ok=False
    if ok and flt.hash_str is not None:
        hs=flt.hash_str; h=item_hash(kind,obj)
        if hs.startswith('!'):
            if h.startswith(hs[1:]): ok=False
        else:
            if not h.startswith(hs): ok=False
    if ok and kind!='todo':
        st,en=item_start_end(kind,obj)
        if flt.start_from is not None and st < flt.start_from: ok=False
        if flt.start_to is not None and st > flt.start_to: ok=False
        if flt.end_from is not None and en < flt.end_from: ok=False
        if flt.end_to is not None and en > flt.end_to: ok=False
    if ok and kind=='todo':
        if flt.priority is not None and c_abs(obj.id)!=flt.priority: ok=False
        if flt.completed and not obj.completed: ok=False
        if flt.uncompleted and obj.completed: ok=False
    return (not ok) if flt.invert else ok

# ---------------- note files ----------------
def note_path(env,name):
    return os.path.join(env.notes_dir,name)
def create_note(env, content):
    if isinstance(content,str): b=content.encode('utf-8','surrogateescape')
    else: b=content
    h=hashlib.sha1(b).hexdigest()
    try:
        with open(note_path(env,h),'wb') as f: f.write(b)
    except OSError: pass
    return h
def read_note(env,name):
    if not name: return None
    try: return open(note_path(env,name),'rb').read()
    except OSError: return None

# ---------------- apts/todo parsing ----------------
class LoadError(Exception):
    def __init__(self,msg): self.msg=msg

def parse_rpt_str(s, io_err):
    """Parse inside-braces recurrence; io_err(msg) raises LoadError with io prefix."""
    m=re.match(r'\s*([+-]?\d+)(.)(.*)$',s,re.S)
    if not m:
        io_err('syntax error in item repetition')
    freq=wrap_i32(int(m.group(1))); typ=m.group(2); rest=m.group(3)
    if typ not in 'DWMY':
        fatal('recur.c: 433','unknown character')
    rpt=Rpt(typ=typ,freq=freq); exc=[]
    tokens=re.findall(r'\S+',rest)
    i=0; last_order=-1; seen_until=False; seen_exc=False
    order={'d':0,'w':1,'m':2}
    def parse_date_token(tok, errmsg):
        mm=re.fullmatch(r'([+-]?\d+)/([+-]?\d+)/([+-]?\d+)',tok or '')
        if not mm: io_err(errmsg)
        mo,da,yr=int(mm.group(1)),int(mm.group(2)),int(mm.group(3))
        if not valid_date(yr,mo,da): io_err(errmsg)
        return days_from_civil(yr,mo,da)
    while i<len(tokens):
        tok=tokens[i]
        if tok.startswith('->'):
            if seen_until or seen_exc or last_order>=0: io_err('missing end of recurrence')
            date_tok=tok[2:]
            if date_tok=="":
                i+=1
                if i>=len(tokens): io_err('until date error')
                date_tok=tokens[i]
            rpt.until=parse_date_token(date_tok,'until date error'); seen_until=True
        elif tok.startswith('!'):
            date_tok=tok[1:]
            if date_tok=="":
                i+=1
                if i>=len(tokens): io_err('missing end of recurrence')
                date_tok=tokens[i]
            exc.append(parse_date_token(date_tok,'missing end of recurrence')); seen_exc=True
        elif tok[0] in 'dwm' and not seen_exc:
            k=tok[0]
            if order[k]<last_order: io_err('missing end of recurrence')
            last_order=order[k]
            resttok=tok[1:]
            if resttok=="" or re.fullmatch(r'[+-]?\d+',resttok) is None:
                if resttok=="":
                    lines={'d':'recur.c: 1640','w':'recur.c: 1659','m':'recur.c: 1678'}
                    msgs={'d':'syntax error in bymonthday','w':'syntax error in bywday','m':'syntax error in bymonth'}
                    fatal(lines[k],msgs[k])
                # a token such as w1.5: integer is read, trailing junk remains
                if re.match(r'[+-]?\d+',resttok):
                    io_err('missing end of recurrence')
                lines={'d':'recur.c: 1640','w':'recur.c: 1659','m':'recur.c: 1678'}
                msgs={'d':'syntax error in bymonthday','w':'syntax error in bywday','m':'syntax error in bymonth'}
                fatal(lines[k],msgs[k])
            v=wrap_i32(int(resttok))
            if k=='d': rpt.bymonthday.append(v)
            elif k=='m':
                if not (1<=v<=12): fatal('recur.c: 1679','illegal bymonth value')
                rpt.bymonth.append(v)
            else:
                # validate bywday according to type
                illegal=False
                if typ in 'DW': illegal=not(0<=v<=6)
                elif typ=='M': illegal=not((0<=v<=41) or (-41<=v<=-7))
                elif typ=='Y': illegal=not((0<=v<=377) or (-377<=v<=-7))
                if illegal: fatal('recur.c: 1661','illegal BYDAY value')
                rpt.bywday.append(v)
        else:
            io_err('missing end of recurrence')
        i+=1
    exc_sorted=sorted(exc)
    return rpt,exc_sorted

def load_apts_file(env: Env, store: Store, flt):
    path=env.apts_path
    try:
        data=open(path,'rb').read()
    except OSError:
        fatal('io.c: 569','failed to open appointment file')
    if data==b'': return
    raw_lines=data.split(b'\n')
    ends_with_nl=data.endswith(b'\n')
    if ends_with_nl: raw_lines=raw_lines[:-1]
    for lineno,raw in enumerate(raw_lines,1):
        has_nl = ends_with_nl or lineno < len(raw_lines)
        line=raw.split(b'\x00')[0]
        if line.endswith(b'\r'): line=line[:-1]
        s=line.decode('utf-8','surrogateescape')
        def io_err(msg, _ln=lineno):
            raise LoadError(f'{path}:{_ln}: {msg}')
        try:
            item=_parse_apt_line(s,has_nl,io_err,env)
        except LoadError as e:
            fatal('io.c: 543', e.msg)
        kind,obj=item
        if not filter_match(flt,kind,obj): continue
        if kind=='event': store.events.append(obj)
        elif kind=='recur-event': store.revents.append(obj)
        elif kind=='apt': store.apts.append(obj)
        else: store.rapts.append(obj)

def _parse_apt_line(s,has_nl,io_err,env):
    m=re.match(r'\s*([+-]?\d+)/([+-]?\d+)/([+-]?\d+)(.*)$',s,re.S)
    if not m: io_err('syntax error in the item date')
    mo,da,yr=int(m.group(1)),int(m.group(2)),int(m.group(3)); rest=m.group(4)
    stripped=rest.lstrip(' \t')
    if stripped.startswith('@'):
        return _parse_appointment(s,mo,da,yr,has_nl,io_err,env)
    if stripped.startswith('['):
        return _parse_event(s,mo,da,yr,has_nl,io_err,env)
    io_err('no event nor appointment found')

def _parse_tail(s, is_apt, has_nl, io_err, env):
    """Parse optional {rpt} and >note at start of s. Returns (rpt,exc,note,rest).
    For appointments rest is positioned at the state character (or after
    the single space following a note token)."""
    rpt=None; exc=[]; note=None
    # recurrence
    t=s.lstrip(' \t')
    if t.startswith('{'):
        close=t.find('}')
        if close<0: io_err('missing end of recurrence')
        inside=t[1:close]
        rpt,exc=parse_rpt_str(inside,io_err)
        t=t[close+1:]
    # note
    t2=t.lstrip(' \t')
    if t2.startswith('>') and len(t2)>1 and t2[1] not in ' \t':
        # token up to whitespace
        mm=re.match(r'>([^ \t]+)(.*)$',t2,re.S)
        if mm:
            note=mm.group(1); rest_after=mm.group(2)
            if is_apt:
                # exactly one space must follow the note token
                if rest_after.startswith(' '):
                    t=rest_after[1:]
                elif rest_after=="":
                    t=""
                else:
                    t=rest_after
            else:
                # event/todo: description follows after one space if present
                if rest_after.startswith(' '): t=rest_after[1:]
                else: t=rest_after
            return rpt,exc,note,t
    return rpt,exc,note,t

def _check_recur(env,io_err,start_day,rpt,exc):
    if rpt is None: return
    if rpt.typ=='W' and rpt.bymonthday:
        io_err('BYMONTHDAY illegal with WEEKLY')
    # start day must be a recurrence day (exceptions ignored here)
    if not is_occurrence_day(start_day,rpt,start_day,env.conf.firstday_monday):
        io_err(f'recurrence error: not on start day ({fmt_date_file(start_day)})')

def _parse_appointment(s,mo,da,yr,has_nl,io_err,env):
    m=re.match(r'\s*[+-]?\d+/[+-]?\d+/[+-]?\d+\s*@\s*([+-]?\d+):([+-]?\d+)\s*->\s*([+-]?\d+)/([+-]?\d+)/([+-]?\d+)\s*@\s*([+-]?\d+):([+-]?\d+)(.*)$',s,re.S)
    if not m: io_err('syntax error in item time or duration')
    h1,mi1=int(m.group(1)),int(m.group(2)); mo2,da2,yr2=int(m.group(3)),int(m.group(4)),int(m.group(5)); h2,mi2=int(m.group(6)),int(m.group(7)); rest=m.group(8)
    if not (valid_date(yr,mo,da) and valid_date(yr2,mo2,da2) and 0<=h1<24 and 0<=mi1<60 and 0<=h2<24 and 0<=mi2<60):
        io_err('illegal date in appointment')
    start=(days_from_civil(yr,mo,da),h1*3600+mi1*60); end=(days_from_civil(yr2,mo2,da2),h2*3600+mi2*60)
    dur=dt_total(end)-dt_total(start)
    if dur<0: io_err('date error in appointment')
    rpt,exc,note,t=_parse_tail(rest,True,has_nl,io_err,env)
    if note is None:
        t=t.lstrip(' \t')
    if not t or t[0] not in '|!':
        io_err('syntax error in item state')
    state=t[0]; mesg=t[1:]
    if mesg=="" and not has_nl:
        io_err('error in appointment description')
    _check_recur(env,io_err,start[0],rpt,exc)
    a=Apt(start=start,dur=dur,state=state,mesg=mesg,note=note,rpt=rpt,exc=exc)
    return ('recur-apt' if rpt else 'apt', a)

def _parse_event(s,mo,da,yr,has_nl,io_err,env):
    m=re.match(r'\s*[+-]?\d+/[+-]?\d+/[+-]?\d+\s*\[\s*([+-]?\d+)\s*\](.*)$',s,re.S)
    if not m: io_err('syntax error in item identifier')
    evid=wrap_i32(int(m.group(1))); rest=m.group(2)
    if not valid_date(yr,mo,da): io_err('illegal date in event')
    day=days_from_civil(yr,mo,da)
    rpt,exc,note,t=_parse_tail(rest,False,has_nl,io_err,env)
    if note is None:
        mesg=t.lstrip(' \t')
    else:
        mesg=t
    _check_recur(env,io_err,day,rpt,exc)
    e=Event(day=day,id=evid,mesg=mesg,note=note,rpt=rpt,exc=exc)
    return ('recur-event' if rpt else 'event', e)

def load_todo_file(env: Env, store: Store, flt):
    path=env.todo_path
    try:
        data=open(path,'rb').read()
    except OSError:
        fatal('io.c: 755','failed to open todo file')
    if data==b'': return
    raw_lines=data.split(b'\n')
    if data.endswith(b'\n'): raw_lines=raw_lines[:-1]
    for lineno,raw in enumerate(raw_lines,1):
        line=raw.split(b'\x00')[0]
        if line.endswith(b'\r'): line=line[:-1]
        s=line.decode('utf-8','surrogateescape')
        def io_err(msg,_ln=lineno): raise LoadError(f'{path}:{_ln}: {msg}')
        try:
            todo=_parse_todo_line(s,io_err)
        except LoadError as e:
            fatal('io.c: 543',e.msg)
        if filter_match(flt,'todo',todo): store.todos.append(todo)

def _parse_todo_line(s,io_err):
    if s.startswith('['):
        close=s.find(']')
        if close<0: io_err('syntax error in item identifier')
        inside=s[1:close]; rest=s[close+1:]
        inner=inside.strip()
        completed=False; idval=None
        if inner.startswith('-'):
            completed=True
            rest_id=inner[1:].strip()
            # rest may itself be signed
            if re.fullmatch(r'[+-]?\d+',rest_id): idval=wrap_i32(int(rest_id))
        else:
            if re.fullmatch(r'[+-]?\d+',inner): idval=wrap_i32(int(inner))
        if idval is None: io_err('syntax error in item identifier')
        # note?
        note=None; t=rest
        t2=t.lstrip(' \t')
        if t2.startswith('>') and len(t2)>1 and t2[1] not in ' \t':
            mm=re.match(r'>([^ \t]+)(.*)$',t2,re.S)
            if mm:
                note=mm.group(1); mesg=mm.group(2).lstrip(' \t')
            else: mesg=t.lstrip(' \t')
        else:
            mesg=t.lstrip(' \t')
        return Todo(id=idval,completed=completed,mesg=mesg,note=note)
    else:
        return Todo(id=9,completed=False,mesg=s.lstrip(' \t'),note=None)

def load_store(env: Env, apts=True,todo=True,hooks=True,flt=None):
    if hooks: run_hook(env,'pre-load')
    store=Store()
    if apts: load_apts_file(env,store,flt)
    if todo: load_todo_file(env,store,flt)
    sort_store(store)
    if hooks: run_hook(env,'post-load')
    env.store=store
    return store

