            n=s[i+1]
            if n=='n': out.append('\n')
            elif n=='t': out.append('\t')
            elif n=='r': out.append('\n')
            elif n=='\\': out.append('\\')
            elif n=='0': out.append('\x00')
            elif n=='a': out.append('\a')
            elif n=='b': out.append('\b')
            elif n=='f': out.append('\f')
