# ---------------- input date parsing ----------------
WEEKDAY_WORDS={
 'sunday':0,'sun':0,'monday':1,'mon':1,'tuesday':2,'tue':2,'wednesday':3,'wed':3,
 'thursday':4,'thu':4,'friday':5,'fri':5,'saturday':6,'sat':6,
}
def parse_input_date(s, fmt):
    """Return days ordinal or None."""
    if s is None: return None
    low=s.lower()
    today=today_days()
    if low in ('today','now'): return today
    if low=='tomorrow': return today+1
    if low=='yesterday': return today-1
    if low in WEEKDAY_WORDS:
        target=WEEKDAY_WORDS[low]; cur=weekday_sun0(today)
        if target>cur: return today+(target-cur)
        return today+7
    if fmt==1: pat=r'(\d+)/(\d+)/(\d+)'; order=('m','d','y')
    elif fmt==2: pat=r'(\d+)/(\d+)/(\d+)'; order=('d','m','y')
    elif fmt==3: pat=r'(\d+)/(\d+)/(\d+)'; order=('y','m','d')
    elif fmt==4: pat=r'(\d+)-(\d+)-(\d+)'; order=('y','m','d')
    else: pat=r'(\d+)/(\d+)/(\d+)'; order=('m','d','y')
    m=re.fullmatch(pat,s)
    if not m: return None
    vals=dict(zip(order,(int(x) for x in m.groups())))
    y,mn,d=vals['y'],vals['m'],vals['d']
    if y==0: return None
    if not valid_date(y,mn,d): return None
    return days_from_civil(y,mn,d)

def parse_input_datetime(s, fmt, end_of_day=False):
    """Parse a filter date/datetime.  Return wall-total seconds or None.
    If no time is given: midnight, except callers asking for an upper
    bound pass end_of_day=True to obtain 23:59:59."""
    if s is None: return None
    parts=s.split(' ')
    # original accepts exactly one space separator? split() handling:
    # use split(' ') semantics: extra spaces make it invalid in most cases
    if len(parts)>2: return None
    day=parse_input_date(parts[0],fmt)
    if day is None: return None
    if len(parts)==1:
        return day*86400 + (86399 if end_of_day else 0)
    tm=parts[1]
    m=re.fullmatch(r'(\d+):(\d+)',tm)
    if not m: return None
    hh,mm=int(m.group(1)),int(m.group(2))
    if not (0<=hh<24 and 0<=mm<60): return None
    return day*86400+hh*3600+mm*60

def parse_date_range_str(s, fmt):
    """For --filter-*-range: return (low,high) wall totals or None on error.
    Either side may be empty (None)."""
    if ',' not in s: return None
    a,b=s.split(',',1)
    # a second comma in b would make b an invalid datetime
    low=None; high=None
    if a!="":
        low=parse_input_datetime(a,fmt,False)
        if low is None: return None
    if b!="":
        high=parse_input_datetime(b,fmt,True)
        if high is None: return None
    return (low,high)

# ---------------- format strings ----------------
def unescape_format(s):
    # Original converts backslash escapes in the format string itself.
    out=[]; i=0
    while i<len(s):
        c=s[i]
        if c=='\\' and i+1<len(s):
            n=s[i+1]
            if n=='n': out.append('\n')
            elif n=='t': out.append('\t')
            elif n=='r': out.append('\n')
            elif n=='\\': out.append('\\')
            elif n=='0': out.append('\x00')
            elif n=='a': out.append('\a')
            elif n=='b': out.append('\b')
            elif n=='f': out.append('\f')
            elif n=='v': out.append('\v')
            elif n=='e': out.append('\x1b')
            else:
                # unknown escape: both characters are dropped (observed \x)
                pass
            i+=2
        else:
            out.append(c); i+=1
    return ''.join(out)

def format_duration_value(total, fmt):
    """Extended %(duration:fmt) / %(remaining:fmt)."""
    if fmt is None or fmt=="": return str(total)
    days=cdiv(total,86400); rem=cmod(total,86400)
    hours=cdiv(rem,3600); rem2=cmod(rem,3600)
    mins=cdiv(rem2,60); secs=cmod(rem2,60)
    out=[]; i=0
    while i<len(fmt):
        c=fmt[i]
        if c!='%': out.append(c); i+=1; continue
        i+=1
        if i>=len(fmt): break
        nopad=False; elapsed=False
        if i<len(fmt) and fmt[i]=='-': nopad=True; i+=1
        if i<len(fmt) and fmt[i]=='E': elapsed=True; i+=1
        if i>=len(fmt): break
        spec=fmt[i]; i+=1
        if spec=='%': out.append('%'); continue
        if spec=='d': v=days
        elif spec=='H': v=cdiv(total,3600) if elapsed else hours
        elif spec=='M': v=cdiv(total,60) if elapsed else mins
        elif spec=='S': v=total if elapsed else secs
        else: out.append('?'); continue
        out.append(str(v) if nopad else f"{v:02d}")
    return ''.join(out)

@dataclass
class FmtCtx:
    kind: str = 'apt'
    obj: object = None
    start: object = None    # wall dt of displayed occurrence (apts)
    day: object = None      # reference day for %S/%E markers
    env: object = None

def _fmt_note_content(env,obj):
    note=getattr(obj,'note',None)
    content=read_note(env,note) if note else None
    if content is None:
        return "\tNo note file found\n"
    text=content.decode('utf-8','surrogateescape')
    out=[]
    # read line by line like fgets: keep newline, prefix tab
    lines=[]
    start=0
    for idx,ch in enumerate(text):
        if ch=='\n': lines.append(text[start:idx+1]); start=idx+1
    if start<len(text): lines.append(text[start:])
    for l in lines: out.append('\t'+l)
    out.append('\n')
    return ''.join(out)

def _time_marker(dt_wall, ref_day):
    d,s=norm_dt(*dt_wall)
    if ref_day is not None and d!=ref_day: return "..:.."
    return fmt_time_file(s)

def format_item(fmt_escaped, ctx: FmtCtx):
    fmt=unescape_format(fmt_escaped)
    obj=ctx.obj; kind=ctx.kind; env=ctx.env
    is_apt = kind in ('apt','recur-apt')
    start_wall=None; end_wall=None; dur=None
    if is_apt:
        start_wall=ctx.start if ctx.start is not None else obj.start
        start_wall=norm_dt(*start_wall)
        dur=obj.dur; end_wall=dt_add_seconds(start_wall,dur)
        ref_day=ctx.day if ctx.day is not None else norm_dt(*obj.start)[0]
    out=[]; i=0
    while i<len(fmt):
        c=fmt[i]
        if c!='%': out.append(c); i+=1; continue
        i+=1
        if i>=len(fmt): break
        spec=fmt[i]
        if spec=='(':
            close=fmt.find(')',i)
            if close<0: break
            inside=fmt[i+1:close]; i=close+1
            if ':' in inside: name,ext=inside.split(':',1)
            else: name,ext=inside,None
            if name=='raw':
                out.append(raw_item(kind,obj)+'\n')
            elif name=='hash':
                out.append(item_hash(kind,obj))
            elif name in ('start','end','duration','remaining') and is_apt:
                if name=='duration':
                    out.append(format_duration_value(dur,ext))
                elif name=='remaining':
                    rem=wall_to_epoch(start_wall)-now_epoch()
                    if ext is None:
                        out.append(f"{cdiv(rem,3600):02d}:{cdiv(cmod(rem,3600),60):02d}")
                    else: out.append(format_duration_value(rem,ext))
                else:
                    dtv=start_wall if name=='start' else end_wall
                    if ext is None or ext=="":
                        out.append(_time_marker(dtv,ref_day))
                    elif ext=="epoch": out.append(str(wall_to_epoch(dtv)))
                    elif ext=="default": out.append(_time_marker(dtv,ref_day))
                    else: out.append(strftime_wall(ext,dtv))
            else:
                out.append('?')
            continue
        i+=1
        if spec=='%': out.append('%'); continue
        if spec=='m': out.append(obj.mesg)
        elif spec=='n': out.append(obj.note if getattr(obj,'note',None) else "(null)")
        elif spec=='N': out.append(_fmt_note_content(env,obj))
        elif is_apt and spec=='d': out.append(str(dur))
        elif is_apt and spec=='s': out.append(str(wall_to_epoch(start_wall)))
        elif is_apt and spec=='e': out.append(str(wall_to_epoch(end_wall)))
        elif is_apt and spec=='S': out.append(_time_marker(start_wall,ref_day))
        elif is_apt and spec=='E': out.append(_time_marker(end_wall,ref_day))
        elif is_apt and spec=='r':
            rem=wall_to_epoch(start_wall)-now_epoch()
            out.append(f"{cdiv(rem,3600):02d}:{cdiv(cmod(rem,3600),60):02d}")
        elif kind=='todo' and spec=='p': out.append(str(c_abs(obj.id)))
        else: out.append('?')
    return ''.join(out)

DEFAULT_QUERY_FORMATS={
 'apt':" - %S -> %E\n\t%m\n", 'recur-apt':" - %S -> %E\n\t%m\n",
 'event':" * %m\n", 'recur-event':" * %m\n", 'todo':"%p. %m\n",
}

class Formats:
    def __init__(self):
        self.user={}  # kind -> format string as given on command line
    def get_query(self,kind):
        return self.user.get(kind, DEFAULT_QUERY_FORMATS[kind])
    def get_grep(self,kind):
        return self.user.get(kind, "%(raw)")

# ---------------- day items & query ----------------
@dataclass
class DayItem:
    kind: str
    obj: object
    start: object = None  # wall dt for apts, None for events

def day_items_for(env: Env, store: Store, day):
    items=[]
    for e in store.events:
        if e.day==day: items.append(DayItem('event',e,None))
    for e in store.revents:
        cand=find_candidate_for_day(e.day,e.rpt,0,e.exc,day,env.conf.firstday_monday)
        if cand==day: items.append(DayItem('recur-event',e,None))
    for a in store.apts:
        st=norm_dt(*a.start); en=dt_add_seconds(st,a.dur)
        if a.dur==0:
            if st[0]==day: items.append(DayItem('apt',a,st))
        else:
            if dt_total(st) < (day+1)*86400 and dt_total(en) > day*86400:
                items.append(DayItem('apt',a,st))
    for a in store.rapts:
        occ=recur_occurrence_on_day(a.start,a.dur,a.rpt,a.exc,day,env.conf.firstday_monday)
        if occ is not None:
            items.append(DayItem('recur-apt',a,occ))
    def key(it):
        if it.kind in ('event','recur-event'):
            return (0,0,bytes_key(it.obj.mesg))
        return (1,dt_total(norm_dt(*it.start)),bytes_key(it.obj.mesg))
    items.sort(key=key)
    return items

def do_query(env: Env, fmts: Formats, first_day, last_day, limit):
    store=env.store
    count=0
    out=[]
    todos=store.todos
    # header decision mirrors original: present when at least one todo
    # will be printed, or replaced by completed header if the completed
    # filter (or -t0 equivalent passed in env) is active
    header_done=False
    if todos:
        # determine whether any todo survives the limit (limit 0 prints none)
        will_print = (limit is None or limit<0 or limit>0)
        if will_print:
            hdr="completed tasks:\n" if getattr(env,'todo_completed_header',False) else "to do:\n"
            out.append(hdr); header_done=True
    for t in todos:
        if limit is not None and limit>=0 and count>=limit: break
        out.append(format_item(fmts.get_query('todo'),FmtCtx('todo',t,None,None,env)))
        count+=1
    day=first_day
    first_section=True
    while day<=last_day:
        items=day_items_for(env,store,day)
        # The date heading is printed if the day has items, or if the
        # limit was already reached during todos/first day (observed).
        show_heading = bool(items)
        if not show_heading and limit is not None and limit>=0 and count>=limit and day==first_day:
            show_heading=True
        if show_heading:
            if header_done or not first_section:
                # separator blank line before each subsequent day and
                # between todos and the first day
                if out and not (len(out)==1 and header_done and not todos):
                    pass
            # Blank line: after todos (if any printed header section)
            # or between days.  Original prints "\n<date>:\n" for a day
            # when something has already been printed, except at start.
            if out:
                out.append("\n")
            datestr=strftime_wall(env.output_fmt(),(day,0))
            out.append(f"{datestr}:\n")
            first_section=False
            for it in items:
                if limit is not None and limit>=0 and count>=limit: break
                ctx=FmtCtx(it.kind,it.obj,it.start,day,env)
                out.append(format_item(fmts.get_query(it.kind),ctx))
                count+=1
        day+=1
    out_bytes(''.join(out))

def do_grep(env: Env, fmts: Formats):
    store=env.store; out=[]
    for t in store.todos: out.append(format_item(fmts.get_grep('todo'),FmtCtx('todo',t,None,None,env)))
    for e in store.revents: out.append(format_item(fmts.get_grep('recur-event'),FmtCtx('recur-event',e,None,e.day,env)))
    for a in store.rapts: out.append(format_item(fmts.get_grep('recur-apt'),FmtCtx('recur-apt',a,a.start,norm_dt(*a.start)[0],env)))
    for a in store.apts: out.append(format_item(fmts.get_grep('apt'),FmtCtx('apt',a,a.start,norm_dt(*a.start)[0],env)))
    for e in store.events: out.append(format_item(fmts.get_grep('event'),FmtCtx('event',e,None,e.day,env)))
    out_bytes(''.join(out))

def do_next(env: Env):
    # next appointment within 24h; current time truncated to the minute
    now_trunc = (now_epoch()//60)*60
    best=None
    # search today and tomorrow (local)
    t=time.localtime(now_trunc); today=days_from_civil(t.tm_year,t.tm_mon,t.tm_mday)
    for day in (today,today+1):
        for it in day_items_for(env,env.store,day):
            if it.kind not in ('apt','recur-apt'): continue
            st=wall_to_epoch(it.start)
            rem=st-now_trunc
            if rem>0 and rem<=86400:
                if best is None or rem<best[0]: best=(rem,it)
    if best:
        rem,it=best
        out_bytes(f"next appointment:\n   [{rem//3600:02d}:{(rem%3600)//60:02d}] {it.obj.mesg}\n")

# ---------------- export ----------------
def ical_escape(s):
    return s.replace('\\','\\\\').replace(';','\\;').replace(',','\\,').replace('\n','\\n')

def parse_note_for_export(env,obj):
    content=read_note(env,getattr(obj,'note',None))
    if content is None: return (None,None,None)
    text=content.decode('utf-8','surrogateescape')
    if text=="": return (None,None,None)
    lines=text.split('\n')
    # If the file ends with '\n', split leaves a trailing ''; the
    # original chops the final newline of the description, and loses
    # the last character when there is no trailing newline.
    had_final_nl=text.endswith('\n')
    if had_final_nl: lines=lines[:-1]
    desc_lines=[]; location=None; comment=None
    in_extra=False; current=None  # 'location' or 'comment'
    desc_done=False
    for idx,line in enumerate(lines):
        if not in_extra:
            if line=='-- ':
                in_extra=True; desc_done=True; continue
            desc_lines.append(line); continue
        # extra section
        if line=='-- ':
            current=None; continue
        if line.startswith('Location: '):
            if location is None: location=line[10:]
            current='location' if location is not None else None
            # if a second Location appears, original keeps the first
            if location is not None and line[10:]!=location and location!=line[10:]:
                # actually keep first: mark current special
                current='ignore'
            continue
        if line.startswith('Comment: '):
            if comment is None: comment=line[9:]
            else: current='ignore'; continue
            current='comment'; continue
        if line.startswith('Import: '):
            current=None; continue
        if line.startswith('    ') and current in ('location','comment'):
            add=line[4:]
            if current=='location': location=location+'\n'+add
            else: comment=comment+'\n'+add
            continue
        current=None
    if not in_extra:
        desc='\n'.join(desc_lines)
        if not had_final_nl and desc:
            desc=desc[:-1]
        return (desc,None,None)
    if desc_lines:
        desc='\n'.join(desc_lines)
    else:
        desc=None
        # A note starting directly with "-- " has no description, but a
        # note consisting of one empty line before the separator has an
        # empty description, represented by desc_lines==[''] (handled).
        if lines and lines[0]=='-- ':
            desc=None
    return (desc,location,comment)

def note_props_lines(env,obj):
    desc,loc,com=parse_note_for_export(env,obj)
    out=[]
    if desc is not None: out.append(f"DESCRIPTION:{ical_escape(desc)}")
    if loc is not None: out.append(f"LOCATION:{ical_escape(loc)}")
    if com is not None: out.append(f"COMMENT:{ical_escape(com)}")
    return out

WDAY_NAMES=['SU','MO','TU','WE','TH','FR','SA']
def byday_token(w):
    o,wd=decode_bywday(w)
    if o==0: return WDAY_NAMES[wd]
    if o>0: return f"+{o}{WDAY_NAMES[wd]}"
    return f"{o}{WDAY_NAMES[wd]}"

def rrule_export(rpt:Rpt, is_event, start_wall):
    freq={'D':'DAILY','W':'WEEKLY','M':'MONTHLY','Y':'YEARLY'}[rpt.typ]
    s=f"FREQ={freq}"
    if rpt.freq>1: s+=f";INTERVAL={rpt.freq}"
    if rpt.until is not None:
        if is_event:
            y,m,d=civil_from_days(rpt.until); s+=f";UNTIL={y:04d}{m:02d}{d:02d}"
        else:
            y,m,d=civil_from_days(rpt.until); st=norm_dt(*start_wall)
            s+=f";UNTIL={y:04d}{m:02d}{d:02d}T{st[1]//3600:02d}{(st[1]%3600)//60:02d}{st[1]%60:02d}"
    if rpt.bymonth: s+=";BYMONTH="+",".join(str(x) for x in rpt.bymonth)
    if rpt.bywday: s+=";BYDAY="+",".join(byday_token(x) for x in rpt.bywday)
    if rpt.bymonthday: s+=";BYMONTHDAY="+",".join(str(x) for x in rpt.bymonthday)
    return s

def export_ical(env: Env, export_uid=False):
    store=env.store; out=[]
    out.append("BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//calcurse//NONSGML v4.8.2//EN\n")
    def uid(kind,obj):
        return f"UID:{item_hash(kind,obj)}\n" if export_uid else ""
    for e in store.revents:
        y,m,d=civil_from_days(e.day)
        out.append("BEGIN:VEVENT\n"+uid('recur-event',e))
        out.append(f"DTSTART;VALUE=DATE:{y:04d}{m:02d}{d:02d}\n")
        out.append(f"RRULE:{rrule_export(e.rpt,True,(e.day,0))}\n")
        if e.exc:
            vals=[]
            for ex in sorted(e.exc):
                yy,mm,dd=civil_from_days(ex); vals.append(f"{yy:04d}{mm:02d}{dd:02d}T000000")
            out.append("EXDATE;VALUE=DATE:"+",".join(vals)+"\n")
        out.append(f"SUMMARY:{ical_escape(e.mesg)}\n")
        for l in note_props_lines(env,e): out.append(l+"\n")
        out.append("END:VEVENT\n")
    for e in store.events:
        y,m,d=civil_from_days(e.day)
        out.append("BEGIN:VEVENT\n"+uid('event',e))
        out.append(f"DTSTART;VALUE=DATE:{y:04d}{m:02d}{d:02d}\n")
        out.append(f"SUMMARY:{ical_escape(e.mesg)}\n")
        for l in note_props_lines(env,e): out.append(l+"\n")
        out.append("END:VEVENT\n")
    for a in list(store.rapts)+list(store.apts):
        kind='recur-apt' if a.rpt else 'apt'
        st=norm_dt(*a.start); y,m,d=civil_from_days(st[0])
        out.append("BEGIN:VEVENT\n"+uid(kind,a))
        out.append(f"DTSTART:{y:04d}{m:02d}{d:02d}T{st[1]//3600:02d}{(st[1]%3600)//60:02d}{st[1]%60:02d}\n")
        if a.dur:
            out.append(f"DURATION:P{a.dur//86400}DT{(a.dur%86400)//3600}H{(a.dur%3600)//60}M{a.dur%60}S\n")
        if a.rpt:
            out.append(f"RRULE:{rrule_export(a.rpt,False,a.start)}\n")
            if a.exc:
                vals=[]
                for ex in sorted(a.exc):
                    yy,mm,dd=civil_from_days(ex); vals.append(f"{yy:04d}{mm:02d}{dd:02d}T{st[1]//3600:02d}{(st[1]%3600)//60:02d}{st[1]%60:02d}")
                out.append("EXDATE:"+",".join(vals)+"\n")
        out.append(f"SUMMARY:{ical_escape(a.mesg)}\n")
        for l in note_props_lines(env,a): out.append(l+"\n")
        if a.state=='!':
            out.append("BEGIN:VALARM\nTRIGGER:-PT300S\nACTION:DISPLAY\nEND:VALARM\n")
        out.append("END:VEVENT\n")
    for t in store.todos:
        out.append("BEGIN:VTODO\n"+uid('todo',t))
        out.append(f"PRIORITY:{t.id}\n")
        out.append(f"SUMMARY:{ical_escape(t.mesg)}\n")
        for l in note_props_lines(env,t): out.append(l+"\n")
        if t.completed: out.append("STATUS:COMPLETED\n")
        out.append("END:VTODO\n")
    out.append("END:VCALENDAR\n")
    out_bytes(''.join(out))

