def _istartswith(s,prefix):
    return s[:len(prefix)].lower()==prefix.lower()

def _import_report(env,lines_read,apps,events,todos,skipped,logentries,version=(2,0),path=""):
    if skipped:
        # write log first so the message below can reference it
        logpath=_write_import_log(version,path,logentries)
        err_bytes(f"\nSome items could not be imported.\nSee {logpath} for details.\n")
    if not env.quiet:
        def pl(n,word): return f"{n} {word}" + ("" if n==1 else "s")
        out_bytes(f"Import process report: {lines_read:04d} lines read\n{pl(apps,'app')} / {pl(events,'event')} / {pl(todos,'todo')} / {skipped} skipped\n")

def _write_import_log(version,path,entries):
    tmpdir=os.environ.get('TMPDIR') or '/tmp'
    # mkstemp-like unique file calcurse_log.XXXXXX (6 chars)
    for _ in range(100):
        suffix=''.join(random.choice(_string.ascii_letters+_string.digits) for _ in range(6))
        p=os.path.join(tmpdir,f"calcurse_log.{suffix}")
        try:
            fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600); break
        except FileExistsError: continue
    else:
        p=os.path.join(tmpdir,"calcurse_log.XXXXXX"); fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600)
    datestr=time.strftime("%x %R",time.localtime())
    def box(content):
        s=f"| {content}"
        if len(s)<68: s=s+' '*(68-len(s))
        return s+"|\n"
    # Build verbatim header.  Interior lines are padded to width 67
    # between the bars; long file names overflow as in the original.
    with os.fdopen(fd,'w',encoding='utf-8',errors='surrogateescape') as f:
        f.write("+-------------------------------------------------------------------+\n")
        f.write(box("Calcurse icalendar import log."))
        f.write(box(""))
        f.write(box("Import from icalendar file"))
        f.write("|       "+path+(' ' * max(0,67-7-len(path)))+"|\n")
        f.write(box(f"version {version[0]}.{version[1]} at {datestr}."))
        f.write(box(""))
        f.write(box("Items which could not be imported are described below."))
        f.write(box("The log line format is as follows:"))
        f.write(box(""))
        f.write(box("      TYPE [LINE]: DESCRIPTION"))
        f.write(box(""))
        f.write(box("where:"))
        f.write(box(" * TYPE is the item type, 'VEVENT' or 'VTODO'"))
        f.write(box(" * LINE is the line in the import file where the item begins"))
        f.write(box(" * DESCRIPTION explains why the item could not be imported"))
        f.write("+-------------------------------------------------------------------+\n")
        f.write("\n")
        for typ,no,msg in entries:
            f.write(f"{typ} [{no}]: {msg}\n")
    return p

