# ---------------- iCalendar import ----------------
ICAL_BUFSIZE=8192

def ical_read_chunks(path):
    """Return list of byte-string chunks as read by fgets(buf,8192)."""
    data=open(path,'rb').read()
    chunks=[]; i=0
    while i<len(data):
        # fgets reads at most 8191 bytes, stopping after a newline
        limit=min(len(data), i+ICAL_BUFSIZE-1)
        nl=data.find(b'\n',i,limit)
        if nl>=0:
            chunks.append(data[i:nl+1]); i=nl+1
        else:
            chunks.append(data[i:limit]); i=limit
    return chunks

def chunk_to_str(chunk):
    b=chunk.split(b'\x00')[0]
    if b.endswith(b'\n'): b=b[:-1]
    if b.endswith(b'\r'): b=b[:-1]
    return b.decode('utf-8','surrogateescape')

def ical_unfold(chunks):
    """Yield (logical_line_str, first_physical_line_number)."""
    lines=[]; i=0
    while i<len(chunks):
        startno=i+1
        s=chunk_to_str(chunks[i]); i+=1
        while i<len(chunks):
            nxt_raw=chunks[i]
            if nxt_raw[:1] in (b' ',b'\t'):
                nxt=chunk_to_str(nxt_raw)
                s+=nxt[1:]
                i+=1
            else: break
        lines.append((s,startno))
    return lines

def split_property(line):
    """Split a content line into (name, params_str, value) honouring
    quoted parameter values.  Return None if no unquoted colon."""
    inq=False
    for idx,ch in enumerate(line):
        if ch=='"': inq=not inq
        elif ch==':' and not inq:
            before=line[:idx]; value=line[idx+1:]
            if ';' in before:
                name,params=before.split(';',1)
                return name.strip(),params,value
            return before.strip(),None,value
    return None

def parse_params(params):
    d={}
    if params is None: return d
    # split on ';' outside quotes
    parts=[]; cur=''; inq=False
    for ch in params:
        if ch=='"': inq=not inq; cur+=ch
        elif ch==';' and not inq: parts.append(cur); cur=''
        else: cur+=ch
    parts.append(cur)
    for p in parts:
        if '=' in p:
            k,v=p.split('=',1); d[k]=v
    return d

def ical_unescape_text(value, summary=False):
    """Return unescaped string or None if malformed."""
    out=[]; i=0
    while i<len(value):
        c=value[i]
        if c in ',;': return None
        if c=='\\':
            if i+1>=len(value):
                out.append('\\'); i+=1; continue
            n=value[i+1]
            if n==',': out.append(',')
            elif n==';': out.append(';')
            elif n=='\\': out.append('\\')
            elif n in 'nN': out.append('\n')
            else: return None
            i+=2; continue
        out.append(c); i+=1
    s=''.join(out)
    if summary: s=s.replace('\n',' ')
    return s

def ical_parse_datetime_value(value):
    """Parse YYYYMMDDTHHMMSS... with sscanf-like leniency.
    Return wall dt or None."""
    m=re.match(r'\s*(\d{4})(\d{2})(\d{1,2})T(\d{2})(\d{2})(\d{1,2})',value)
    if not m: return None
    y,mo,da,hh,mm,ss=(int(x) for x in m.groups())
    days=days_from_civil(y,mo,da)
    return norm_dt(days,hh*3600+mm*60+ss)

def ical_parse_date_value(value):
    if re.fullmatch(r'\d+',value) is None: return None
    m=re.match(r'^(\d{4})(\d{2})(\d{1,2})$',value)
    if not m:
        # sscanf %4d%2d%2d against e.g. 7 digits gives a day of 0 etc;
        # fullmatch above with 1-2 digit day covers observed cases.
        return None
    y,mo,da=(int(x) for x in m.groups())
    return days_from_civil(y,mo,da)

def ical_parse_duration(value, is_date):
    """Return seconds >0 or None.  For date events only the day/week
    component counts."""
    s=value
    sign=1
    if s.startswith('+'): s=s[1:]
    if s.startswith('-'): return None
    if not s.startswith('P'): return None
    rest=s[1:]
    # sscanf skips whitespace before numbers, so tolerate it crudely
    # week form: nW
    m=re.match(r'\s*([+-]?\d+)W',rest)
    if m:
        v=int(m.group(1))
        total=(v & 0xffffffff)*604800 if v<0 else v*604800
        # emulate 32-bit overflow in the C multiplication for huge values
        total=wrap_i32(total) if abs(total)>=2**31 else total
        if v<0: total=(v & 0xffffffff)*604800  # unsigned wrap behaviour approximated below in caller
        return total if total>0 else None
    days=0; has_days=False
    m=re.match(r'\s*([+-]?\d+)D',rest)
    if m:
        days=int(m.group(1)); has_days=True; rest=rest[m.end():]
    hours=mins=secs=0; has_time=False
    if rest.startswith('T'):
        rest=rest[1:]; has_time=True
        # components in H,M,S order, each optional, sscanf leniency:
        # consume number+designator pairs while they look plausible;
        # values parsed out of order and trailing junk are ignored by
        # the original pattern attempts, so collect recognised ones.
        pos=0
        vals={}
        while pos<len(rest):
            mm=re.match(r'\s*([+-]?\d+)([HMS])',rest[pos:])
            if not mm: break
            vals[mm.group(2)]=int(mm.group(1)); pos+=mm.end()
            if len(vals)>=3: break
        hours=vals.get('H',0); mins=vals.get('M',0); secs=vals.get('S',0)
    if not has_days and not has_time: return None
    if is_date:
        if not has_days: return None
        total=days*86400
        return total if total>0 else None
    # unsigned-ish overflow emulation for negative components is not
    # attempted beyond keeping Python integers
    def u32(x): return x & 0xffffffff
    total = (u32(days)*86400 if days<0 else days*86400) + (u32(hours)*3600 if hours<0 else hours*3600) + (u32(mins)*60 if mins<0 else mins*60) + (u32(secs) if secs<0 else secs)
    if days>=0 and hours>=0 and mins>=0 and secs>=0:
        # C unsigned int multiplication wraps for very large components
        total = ((days*86400) & 0xffffffff) + ((hours*3600)&0xffffffff) + ((mins*60)&0xffffffff) + secs
        # The wraps above are only observable for absurd durations;
        # recompute plainly when nothing overflowed:
        if days<50000 and hours<1000000 and mins<10000000:
            total=days*86400+hours*3600+mins*60+secs
    return total if total>0 else None

def format_labelled(label, value):
    parts=value.split('\n')
    out=[f"{label}: {parts[0]}\n"]
    for p in parts[1:]: out.append(f"    {p}\n")
