# ---------------- garbage collector / status ----------------
def do_gc(env):
    used=set()
    for coll in (env.store.todos,env.store.events,env.store.revents,env.store.apts,env.store.rapts):
        for o in coll:
            if getattr(o,'note',None): used.add(o.note)
    try:
        names=os.listdir(env.notes_dir)
    except OSError:
        return
    for name in names:
        if name.startswith('.'): continue
        p=os.path.join(env.notes_dir,name)
        if os.path.isdir(p) and not os.path.islink(p): continue
        if name not in used:
            try: os.remove(p)
            except OSError: pass

def read_pidfile(path):
    try:
        data=open(path,'rb').read(64)
    except OSError:
        return 0
    return atoi_c(data.decode('utf-8','surrogateescape'))

def do_status(env):
    cal_pid=read_pidfile(env.pid_path); dmn_pid=read_pidfile(env.daemon_pid_path)
    if cal_pid and dmn_pid:
