        sys.exit(1)
    if cal_pid: out_bytes(f"calcurse is running (pid {cal_pid})\n")
    elif dmn_pid: out_bytes(f"calcurse is running in background (pid {dmn_pid})\n")
    else: out_bytes("calcurse is not running\n")

def daemon_loop(env):
    # child process
    try:
        os.setsid()
    except Exception: pass
    pidfile=env.daemon_pid_path
    log_enabled=env.conf.get_bool('daemon.log',False)
    def dlog(msg):
        if log_enabled:
            try:
                with open(env.daemon_log_path,'a') as f: f.write(msg)
            except OSError: pass
    def onterm(signum,frame):
        try: os.remove(pidfile)
        except OSError: pass
        if log_enabled:
            try:
                with open(env.daemon_log_path,'a') as f:
                    f.write(f"terminated at {time.strftime('%a %b %d %H:%M:%S %Y',time.localtime())} with signal {signum}\n")
            except OSError: pass
        sys.exit(0)
    signal.signal(signal.SIGTERM,onterm)
    signal.signal(signal.SIGINT,onterm)
    try:
        with open(pidfile,'w') as f: f.write(f"{os.getpid()}\n")
    except OSError:
        sys.exit(1)
    # original daemon exits quietly if the appointments file is absent
    if not os.path.exists(env.apts_path):
        try: os.remove(pidfile)
        except OSError: pass
        sys.exit(0)
    dlog(f"started at {time.strftime('%a %b %d %H:%M:%S %Y',time.localtime())}\n")
    warned=set()
    while True:
        dlog(f"sleeping at {time.strftime('%a %b %d %H:%M:%S %Y',time.localtime())} for 60 seconds\n")
        # check for upcoming appointments to notify about, once a minute
        try:
            st=Store(); load_apts_file(env,st,None); env.store=st
            nowt=now_epoch(); warn=atoi_c(env.conf.values.get('notification.warning','300'))
            notifyall=env.conf.values.get('notification.notifyall','flagged-only')
            cmd=env.conf.values.get('notification.command',"printf '\\a'")
            t=time.localtime(); today=days_from_civil(t.tm_year,t.tm_mon,t.tm_mday)
            for day in (today,today+1):
                for it in day_items_for(env,st,day):
                    if it.kind not in ('apt','recur-apt'): continue
                    if notifyall in ('flagged-only','yes') and it.obj.state!='!': continue
                    if notifyall in ('unflagged-only','no') and it.obj.state=='!': continue
                    stt=wall_to_epoch(it.start)
                    key=(stt,it.obj.mesg)
                    if 0 < stt-nowt <= warn and key not in warned:
                        warned.add(key)
                        shell=os.environ.get('SHELL','/bin/sh')
                        try: subprocess.run([shell,'-c',cmd],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
                        except Exception: pass
                        dlog(f"notification sent for: {it.obj.mesg}\n")
        except SystemExit:
            try: os.remove(pidfile)
            except OSError: pass
            raise
        except Exception:
            pass
        time.sleep(60)

def do_daemon(env):
    # restart an already running daemon, as the original does
    old=read_pidfile(env.daemon_pid_path)
    if old:
        try:
            os.kill(old,signal.SIGTERM)
            for _ in range(20):
                time.sleep(0.05)
                try: os.kill(old,0)
                except OSError: break
        except OSError: pass
    pid=os.fork()
    if pid>0:
        return
