    try:
        sys.stdout.flush(); sys.stderr.flush()
    except Exception: pass
    fd=os.open(os.devnull,os.O_RDWR)
    os.dup2(fd,0); os.dup2(fd,1); os.dup2(fd,2)
    daemon_loop(env)
