def gnu_getopt(argv, prog):
    opts=[]; nonopts=[]
    i=0; end=False
    posix = 'POSIXLY_CORRECT' in os.environ
    while i<len(argv):
        arg=argv[i]
        if end:
            nonopts.append(arg); i+=1; continue
        if arg=='--':
            end=True; i+=1; continue
        if posix and (not arg.startswith('-') or arg=='-'):
            nonopts.extend(argv[i:]); break
        if not arg.startswith('-') or arg=='-':
            nonopts.append(arg); i+=1; continue
        if arg.startswith('--'):
            body=arg[2:]
            if '=' in body: name,attached=body.split('=',1); has_attached=True
            else: name,attached,has_attached=body,None,False
            exact=[o for o in LONG_OPTIONS if o[0]==name]
            cands=exact if exact else [o for o in LONG_OPTIONS if o[0].startswith(name)]
            if not cands:
                raise GetoptError(f"{prog}: unrecognized option '{arg}'\n")
            behaviours=[]
            for c in cands:
                if c[1] not in behaviours: behaviours.append(c[1])
            if not exact and len(behaviours)>1:
                poss=' '.join(f"'--{c[0]}'" for c in cands)
                raise GetoptError(f"{prog}: option '{arg}' is ambiguous; possibilities: {poss}\n")
            lname,oid,atype=cands[0]
            if atype=='no' and has_attached:
                raise GetoptError(f"{prog}: option '--{lname}' doesn't allow an argument\n")
            if atype=='req':
                if has_attached: val=attached
                else:
                    if i+1>=len(argv): raise GetoptError(f"{prog}: option '--{lname}' requires an argument\n")
                    i+=1; val=argv[i]
