        j=1
        while j<len(arg):
            ch=arg[j]
            if ch not in SHORT_OPTIONS:
                raise GetoptError(f"{prog}: invalid option -- '{ch}'\n")
            oid,atype=SHORT_OPTIONS[ch]
            if atype=='no':
                opts.append((oid,None)); j+=1; continue
            if atype=='req':
                if j+1<len(arg): opts.append((oid,arg[j+1:])); j=len(arg)
                else:
                    if i+1>=len(argv): raise GetoptError(f"{prog}: option requires an argument -- '{ch}'\n")
