def main(argv=None):
    if argv is None: argv=sys.argv
    prog=argv[0] if argv else 'calcurse'
    args=argv[1:]
    try:
        opts,nonopts=gnu_getopt(args,prog)
    except GetoptError as e:
        out_bytes(USAGE_TRY); err_bytes(e.msg); return 1
    # extract directories, resolve paths and load configuration
    datadir_arg=None; confdir_arg=None; cal_arg=None
    for oid,val in opts:
        if oid=='D': datadir_arg=val
        elif oid=='C': confdir_arg=val
        elif oid=='c': cal_arg=val
    env=Env()
    env.datadir,env.confdir=resolve_dirs(datadir_arg,confdir_arg)
    env.calendarfile=cal_arg
    env.conf=load_config(env.conf_path)
    a=parse_semantics(opts,env)
    # combination validation
    groups=[]
    if a.query: groups.append('query')
    if a.next: groups.append('next')
    if a.grep or a.purge or a.filterop: groups.append('grep')
    if a.export: groups.append('export')
    if a.import_file is not None: groups.append('import')
    if a.gc: groups.append('gc')
    if a.status: groups.append('status')
    if a.daemon: groups.append('daemon')
    invalid=False
    if nonopts: invalid=True
    if len(groups)>1: invalid=True
    if a.purge and a.filter.invert: invalid=True
    if a.has_filter:
        if not (a.query or a.grep or a.purge or a.filterop or a.export): invalid=True
    if a.has_format:
        if not (a.query or a.grep or a.purge or a.filterop or (a.import_file is not None and a.dump_imported)): invalid=True
    if a.has_range:
        if not a.query: invalid=True
    if invalid:
        fatal('args.c: 880','invalid argument combination')
    # range conflicts for query
    if a.query:
        if a.to_set and a.days_set:
            fatal('args.c: 882','cannot specify a range and an end date')
        first=a.from_day if a.from_set else today_days()
        if a.to_set:
            last=a.to_day
            if last<first: fatal('args.c: 887','end date cannot come before start date')
        elif a.days_set:
            n=a.days
            if n>0: last=first+n-1
            else: last=first; first=first+n+1
        else:
            last=first
        a.range_first=first; a.range_last=last
    # no operation selected
    if not groups:
        if a.datefmt_noninteractive:
            check_dirs(env); return 0
        return run_interactive(env,a)
    # explicit calendar file must exist (before creating directories)
    if cal_arg is not None and not os.path.exists(cal_arg):
        fatal('io.c: 189',f'{cal_arg} does not exist')
    check_dirs(env)
    # file creation per operation
    if a.query or a.grep or a.purge or a.filterop:
        check_files(env,apts=True,todo=True,conf=True)
    elif a.export or a.gc or a.import_file is not None:
        check_files(env,apts=True,todo=True,conf=False)
    elif a.next:
        check_files(env,apts=True,todo=False,conf=False)
    # execute
    if a.status:
        do_status(env); return 0
    if a.daemon:
        do_daemon(env); return 0
    if a.next:
        load_store(env,apts=True,todo=False,hooks=False,flt=None)
        do_next(env); return 0
    # groups needing the full store
    if a.purge:
        pf=Filter()
        pf.__dict__.update(a.filter.__dict__); pf.invert=not a.filter.invert
        load_store(env,apts=True,todo=True,hooks=True,flt=pf)
        write_store_files(env); return 0
    if a.filterop and not a.grep:
        # pure -F, or -F with -G if purge not set: filter wins over grep
        load_store(env,apts=True,todo=True,hooks=True,flt=a.filter)
        write_store_files(env); return 0
    if a.filterop:
        load_store(env,apts=True,todo=True,hooks=True,flt=a.filter)
        write_store_files(env); return 0
    if a.grep:
        load_store(env,apts=True,todo=True,hooks=True,flt=a.filter)
        do_grep(env,a.formats); return 0
    if a.query:
        load_store(env,apts=True,todo=True,hooks=True,flt=a.filter)
        env.todo_completed_header=bool(a.filter.completed)
        do_query(env,a.formats,a.range_first,a.range_last,a.limit)
        return 0
    if a.export:
        load_store(env,apts=True,todo=True,hooks=True,flt=a.filter)
        if a.export_format=='pcal': export_pcal(env)
        else: export_ical(env,export_uid=a.export_uid)
        return 0
    if a.import_file is not None:
        load_store(env,apts=True,todo=True,hooks=True,flt=None)
        sort_store(env.store)
        return do_import(env,a.import_file,a.formats,dump_imported=a.dump_imported)
    if a.gc:
        load_store(env,apts=True,todo=True,hooks=True,flt=None)
        do_gc(env); return 0
    return 0

