import subprocess, shutil, os, re, glob
ORIG="/tmp/original_calcurse"; NEW="./executable"
for f in glob.glob('/tmp/calcurse_log.*'):
    try:os.remove(f)
    except:pass
def norm(b):
    b=re.sub(rb'/tmp/calcurse_log\.[A-Za-z0-9]+',b'/tmp/calcurse_log.XXXXXX',b)
    b=b.replace(b'/tmp/original_calcurse',b'./executable')
    return b
def compare(label, actions, apts="",todo="",conf="",notes=None, extra_files=None, env_extra=None):
    outcomes=[]
    for exe,tag in [(ORIG,'orig'),(NEW,'new')]:
        d=f"/tmp/cmp_{tag}"; shutil.rmtree(d,ignore_errors=True); os.makedirs(f"{d}/data/notes"); os.makedirs(f"{d}/conf/hooks")
        open(f"{d}/data/apts","w").write(apts); open(f"{d}/data/todo","w").write(todo); open(f"{d}/conf/conf","w").write(conf)
        if notes:
            for k,v in notes.items(): open(f"{d}/data/notes/{k}","w").write(v)
        if extra_files:
            for rel,content in extra_files.items():
                p=os.path.join(d,rel); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,'wb').write(content if isinstance(content,bytes) else content.encode())
        rec=[]
        env=os.environ.copy()
        if env_extra: env.update(env_extra)
        for args in actions:
            # actions can be list (prefixed D/C) or ('RAW',[...]) full args no prefix
            if args and args[0]=='RAW': full=[exe]+args[1:]
            else: full=[exe,"-D",f"{d}/data","-C",f"{d}/conf"]+args
            # clean log before to capture content if stderr
            before=set(glob.glob('/tmp/calcurse_log.*'))
            try:
                r=subprocess.run(full,capture_output=True,timeout=5,env=env)
                out,err,rc=norm(r.stdout),norm(r.stderr),r.returncode
            except Exception as e:
                out,err,rc=b'',str(e).encode(),-999
            after=set(glob.glob('/tmp/calcurse_log.*'))-before
            logs=[]
            for lp in sorted(after):
                try:
                    content=open(lp,'rb').read(); content=re.sub(rb'version .*? at .*?\.',b'version X at Y.',content); logs.append(content)
                except:pass
                try:os.remove(lp)
                except:pass
            rec.append((tuple(args),rc,out,err,tuple(logs)))
            # daemon cleanup
            p=f"{d}/data/.daemon.pid"
            if os.path.exists(p):
                try:os.kill(int(open(p).read().strip()),15)
                except:pass
        snap={}
        for root,dirs,files in os.walk(d):
            dirs.sort()
            for f in sorted(files):
                p=os.path.join(root,f); rel=os.path.relpath(p,d)
                content=open(p,'rb').read()
                if rel in ('data/.daemon.pid','data/.calcurse.pid'): content=b'<pid>'
                if rel=='data/daemon.log': content=re.sub(rb'at .*?(?=\n| for)',b'at X',content)
                snap[rel]=content
            for dd in dirs: snap[os.path.relpath(os.path.join(root,dd),d)+'/']=None
        outcomes.append((rec,snap))
    ok=outcomes[0]==outcomes[1]
    print(("OK   " if ok else "FAIL ")+label)
    if not ok:
        (r1,s1),(r2,s2)=outcomes
        for x,y in zip(r1,r2):
            if x!=y: print(" RUN orig",x,"\n     new ",y)
        if s1!=s2:
            for k in sorted(set(s1)|set(s2)):
                if s1.get(k)!=s2.get(k): print(" FILE",k,"orig",repr(s1.get(k))[:3000],"\n      new",repr(s2.get(k))[:3000])
    return ok
