        alive=False
        try: os.kill(calpid,0); alive=True
        except OSError: alive=False
        if alive:
            err_bytes(f"\\nWARNING: it seems that another calcurse instance is already running.\\nIf this is not the case, please remove the following lock file: \\n\\"{env.pid_path}\\"\\nand restart calcurse.\\n")
            return 1
