        with open(env.pid_path,'w') as _f: _f.write(f"{os.getpid()}\\n")
    except OSError: pass
    # terminal initialisation happens before data are loaded in the
    # original; a bad TERM therefore leaves the pid file in place.
    try:
        stdscr=curses.initscr()
    except Exception:
        err_bytes(f"Error opening terminal: {os.environ.get('TERM') or 'unknown'}.\\n")
