import re
s=open('/tmp/keyhelps.txt').read().split('--- ')
for sec in s[1:]:
 lines=sec.splitlines();title=None;desc=[]
 for i,l in enumerate(lines):
  m=re.search(r'│ │\s+([a-z-]+\S*)\s+│ │',l)
  if m and title is None:title=m.group(1)
 # description is a line with text centered and not a keys line (heuristic: after title, find lines containing '│ │' and strip, non-empty, not divider)
 cand=[]
 started=False
 for l in lines:
  if title and title in l:started=True;continue
  if started:
   t=l.strip('│ ').strip()
   # Actually l has outer and inner borders; extract between inner borders if present
   parts=l.split('│')
   if len(parts)>=3:t=parts[2].strip()
   if t and not set(t)<=set('─'):cand.append(t)
 print(title,'=>',cand[:3])
PY
